CREATE TABLE series (
    series_id       INTEGER PRIMARY KEY AUTOINCREMENT,
    series_name     TEXT NOT NULL,
    category        TEXT NOT NULL,              -- horror, facts, motivational, mystery, etc.
    format          TEXT NOT NULL,               -- short | long_continuous | long_compilation
    status          TEXT NOT NULL DEFAULT 'active',  -- active | concluded | on_hold
    current_part    INTEGER NOT NULL DEFAULT 0,
    total_parts_planned INTEGER,                 -- nullable = open-ended
    canon_facts     TEXT NOT NULL DEFAULT '[]',   -- JSON array of strings
    characters      TEXT NOT NULL DEFAULT '{}',   -- JSON object: {name: {role, traits, status}}
    unresolved_threads TEXT NOT NULL DEFAULT '[]', -- JSON array of strings
    last_episode_summary TEXT DEFAULT '',
    created_at      TEXT NOT NULL DEFAULT (datetime('now')),
    updated_at      TEXT NOT NULL DEFAULT (datetime('now')),
    last_video_date TEXT
);
INSERT INTO "series" VALUES(1,'The Keeper''s Last Entry: The Light Must Never Stop','horror','long_continuous','active',1,NULL,'["Elias was the lighthouse keeper and vanished before the episode begins.", "The lighthouse''s revolving lens made a complete sweep every nine seconds.", "Elias''s logbook warned that if the beam rested on the water for more than three seconds, something below would notice it could see.", "Under the final logbook entry, Elias had written: ''It already knows the pattern. It is learning to count.''", "Builder records from 1923 called the revolving lens a ''blindfold'' and recorded crew claims that a fixed light had blinked over pale water before wrecks.", "A first-keeper letter warned: ''A moving light is a broom. A still light is a hand.''", "The narrator''s work order was signed ''Elias K\u2014'' but in a rounded, watery handwriting different from Elias''s; the coastguard said no archive order existed and no crew had been requested in six years.", "A hidden iron door at the tower''s base, absent from blueprints, led to stairs descending into dark, still, non-salty water; walls were covered in a wax-like substance.", "The radio voice warned the narrator: if he saw a light inside the water, he must not let the beam stop.", "A wet, twitching rope was found jammed in the lighthouse drive chain; after removing it, three knocks then two knocks came from the sealed room below.", "When the beam stopped, a pale gold light under the water traveled along the beam toward the tower, and Elias appeared standing on the seabed.", "Elias said the narrator''s greasing of the shaft made it smooth, allowing the entity to count the pauses and learn the rhythm.", "The narrator broke the lens with an iron tool, extinguishing the light; the underwater glow collapsed and the tower was dark for the first time in a hundred years.", "The narrator was found the next morning on the lower rocks, covered in salt and glass dust; the coastguard called the dark tower a generator failure.", "In the open sealed room, a warm brass key lay at the bottom of a perfectly round pool, inscribed: ''If the light finds you, thank it. It has brought a guest.''", "The narrator does not know if the creature is gone, and now sometimes sees beams from abandoned lighthouses moving in perfect rhythm, one sweep every nine seconds."]','{"Narrator": {"role": "archive/records retriever", "status": "alive", "notes": "Broke the lighthouse lens to extinguish the light; found on rocks the next morning; now haunted by coastline beams and does not stop to look."}, "Elias K\u2014": {"role": "lighthouse keeper", "status": "missing", "notes": "Vanished before the episode; seen in the water standing on the seabed during the climax, speaking an apology; final fate unknown."}, "Ferryman": {"role": "ferryman", "status": "alive", "notes": "Brought narrator to the old jetty; recounted the strange final supply run with Elias."}, "Coastguard radio voice": {"role": "coastguard (unidentified)", "status": "unknown", "notes": "Said no archive order existed; warned to keep the beam moving and seemed to know more than he said."}}','["Elias''s actual fate and what he became or where he is, since he was seen under the water but no body was recovered.", "Whether the entity is truly gone; the narrator admits he does not know if it ever left.", "Who sent the work order? It was signed ''Elias K\u2014'' in a different handwriting, and no archive order existed.", "The sealed room and its hidden stair into dark water: purpose unknown; the iron door was open at the end.", "The warm brass key with the inscription ''If the light finds you, thank it. It has brought a guest'' \u2014 what it opens and what the inscription means.", "The coastguard who warned about the light: how did he know, and who was he?", "The narrator''s recurring lighthouse beams: whether the entity is still active or trying to lure him.", "Whether the ''guest'' mentioned on the key refers to the narrator or to something else remains unknown."]','An unnamed archive collector visits a remote lighthouse to retrieve records, discovers that keeper Elias vanished, and finds logbook entries warning that the beam must never stop. When the lens is accidentally allowed to stop, a creature''s light travels up the beam, Elias appears in the water, and the collector smashes the lens to extinguish the tower light. He survives but later finds a mysterious key in a sealed room and remains uncertain whether the creature is gone.','2026-08-12 04:41:15','2026-08-12T04:42:11.336118+00:00','2026-08-12T04:42:11.336118+00:00');
CREATE TABLE videos (
    video_id        INTEGER PRIMARY KEY AUTOINCREMENT,
    series_id       INTEGER REFERENCES series(series_id),  -- NULL if standalone
    series_part     INTEGER,                     -- part number within series, NULL if standalone
    category        TEXT NOT NULL,
    format          TEXT NOT NULL,                -- short | long_continuous | long_compilation
    style           TEXT NOT NULL,                -- A (ai_images) | B (stock) | C (avatar)
    title           TEXT,
    hook_line       TEXT,
    ending_line     TEXT,
    cta             TEXT,
    script_json     TEXT,                         -- full structured script, JSON
    script_hash     TEXT,                         -- to detect near-duplicate content
    audio_path      TEXT,
    video_path       TEXT,
    thumbnail_path  TEXT,
    youtube_video_id TEXT,
    status          TEXT NOT NULL DEFAULT 'pending', -- pending | scripted | voiced | assembled | uploaded | failed
    error_message   TEXT,
    created_at      TEXT NOT NULL DEFAULT (datetime('now')),
    uploaded_at     TEXT
, visual_manifest_path TEXT);
INSERT INTO "videos" VALUES(1,NULL,NULL,'mystery','short','A','The Funeral Woman''s Envelope: A Mystery','The funeral woman left me an envelope with my name on it and a date: tomorrow.','I left that job the next morning. Last month, they broke through the wall again. There was a new envelope with my name on it — and a new date.','Tell me what you think the new date means in the comments — and subscribe so you''re here for the reveal.','{"title": "The Funeral Woman''s Envelope: A Mystery", "hook_line": "The funeral woman left me an envelope with my name on it and a date: tomorrow.", "intro_line": "This happened in the archive room where I used to work.", "scenes": [{"narration": "I filed death certificates for ten years, so I knew every face that came through the door. She came to forty-two funerals, always in gray, always silent, always gone before the burial.", "visual_prompt": "Dusty archive office with metal filing cabinets; a woman in gray is barely visible in the background."}, {"narration": "On the forty-third funeral, she stopped, pressed an envelope into my hand, and vanished before the door stopped swinging.", "visual_prompt": "Church interior; a gray-gloved hand slides a white envelope across a wooden pew; light from the door moves."}, {"narration": "The card inside had my full name, a date, and a county file number. The archive index said the file with that number was sealed in the vault in 1931. But when we reached the vault, it was locked from the inside.", "visual_prompt": "Dark hallway leading to a heavy vault door; narrator reads a small card under dim light."}, {"narration": "They cut through the wall. Inside was one photograph: the funeral woman beside a gravestone. My name was on the stone. The carved date was tomorrow.", "visual_prompt": "Inside the vault, a single framed photograph lies on the floor; the photo shows a woman in gray at a headstone."}], "ending_line": "I left that job the next morning. Last month, they broke through the wall again. There was a new envelope with my name on it \u2014 and a new date.", "cta": "Tell me what you think the new date means in the comments \u2014 and subscribe so you''re here for the reveal.", "youtube_description": "A strange mystery from a death-certificate archive. A funeral regular leaves an envelope that leads to a locked vault, and what comes out changes everything. What do you think the new date means? Tell us in the comments and subscribe for more mysteries.", "tags": ["funeral mystery", "archive mystery", "short mystery story", "locked vault", "creepy stories", "unexplained mystery", "mystery narration", "strange story"]}','9abb0d93731bd351','C:\Users\saina\Videos\YT Automation\assets\audio\video_1.mp3','C:\Users\saina\Videos\YT Automation\output\video_1.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_1_thumbnail.png','FCOtFdUrBI4','uploaded',NULL,'2026-08-10 15:40:36','2026-08-11T09:08:26.476269+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_1_manifest.json');
INSERT INTO "videos" VALUES(8,NULL,NULL,'horror','short','A','The Mirror in My Hallway Stopped Showing What Was Behind Me','The mirror in my hallway doesn''t show what''s behind me anymore.','I don''t know what''s on the other side. But I know it''s not my reflection anymore.','Have you ever seen something in a mirror that didn''t move when you did? Tell me in the comments, and subscribe to Night Loom for more.','{"title": "The Mirror in My Hallway Stopped Showing What Was Behind Me", "hook_line": "The mirror in my hallway doesn''t show what''s behind me anymore.", "intro_line": "Here on Night Loom, I tell the stories that make you double-check your mirrors.", "scenes": [{"narration": "The first sign was a shadow at the edge of the glass \u2014 too tall to be mine, too still to be the coat rack. I told myself it was a trick of the light.", "visual_prompt": "A dim hallway mirror reflecting a normal room, with a subtle tall shadow lingering at the edge of the frame."}, {"narration": "Last night I turned off every lamp and stood in front of it. The room behind me went dark. But in the mirror, there was a shape standing exactly where I knew no one could be.", "visual_prompt": "A person facing a mirror in near-total darkness, a faint humanoid silhouette visible only in the reflection."}, {"narration": "I waited. It didn''t move. So I took one step forward. The shape took a step closer \u2014 not toward me, but toward the glass, as if it wanted out.", "visual_prompt": "The silhouette in the mirror stepping closer to the glass surface while the person in front stays still."}, {"narration": "I grabbed the mirror and flipped it to face the wall. That was an hour ago. But now I can hear something scratching the back of the glass from inside.", "visual_prompt": "A mirror lying face-down against a wall, with faint scratch marks appearing on the backing as a low scraping sound echoes."}], "ending_line": "I don''t know what''s on the other side. But I know it''s not my reflection anymore.", "cta": "Have you ever seen something in a mirror that didn''t move when you did? Tell me in the comments, and subscribe to Night Loom for more.", "youtube_description": "A hallway mirror, a shadow that shouldn''t exist, and the sound of something scratching from inside the glass. This is the story of why I turned the mirror to face the wall. If you enjoy quiet, creeping horror, subscribe to Night Loom for more.", "tags": ["horror story", "night loom", "mirror horror", "creepy story", "short horror", "unexplained", "dark storytelling"]}','dd08757b4bb3edab','C:\Users\saina\Videos\YT Automation\assets\audio\video_8.mp3','C:\Users\saina\Videos\YT Automation\output\video_8.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_8_thumbnail.png','aeyUKkW9FpQ','uploaded',NULL,'2026-08-11 09:44:24','2026-08-11T11:09:39.040997+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_8_manifest.json');
INSERT INTO "videos" VALUES(9,NULL,NULL,'motivational','short','A','The Worst Performance of My Career Saved Me','The worst performance of my career was also the best thing that ever happened to me.','The panic didn''t disappear. It just stopped being louder than my preparation.','If this story moved you, subscribe for daily motivation — I''ll be here tomorrow with another one.','{"title": "The Worst Performance of My Career Saved Me", "hook_line": "The worst performance of my career was also the best thing that ever happened to me.", "intro_line": "Welcome to Night Loom, and this is a story about what happened after I walked off that stage.", "scenes": [{"narration": "I had rehearsed for three weeks. I knew every number, every slide. But when I looked up, the room turned to static.", "visual_prompt": "A person standing alone on a stage, lights blurring into haze, audience silhouettes."}, {"narration": "I froze. I stumbled over a sentence. And then I said ''I don''t know'' and walked off. The silence in that room lasted forever.", "visual_prompt": "Close-up of a speaker''s hands gripping the podium, then cut to empty chair backstage."}, {"narration": "The next morning my boss didn''t fire me. She asked, ''What actually went wrong?'' And for the first time I told the truth: ''I never practiced out loud. I only rehearsed in my head.''", "visual_prompt": "A quiet office, two cups of coffee, a manager looking at the employee with calm attention."}, {"narration": "So I started practicing every talk out loud, alone, for thirty days. The next presentation wasn''t perfect. But it was real.", "visual_prompt": "A person pacing in an empty living room, speaking to a wall, then cutting to them on stage, steady."}], "ending_line": "The panic didn''t disappear. It just stopped being louder than my preparation.", "cta": "If this story moved you, subscribe for daily motivation \u2014 I''ll be here tomorrow with another one.", "youtube_description": "I bombed a presentation in front of everyone and thought it was over. It turned out to be the moment I needed, and this is what happened next. Subscribe to Night Loom for stories that get to the point.", "tags": ["motivation", "personal growth", "public speaking", "failure", "resilience", "Night Loom", "true story", "self improvement"]}','8f0d8dff97e40d33','C:\Users\saina\Videos\YT Automation\assets\audio\video_9.mp3','C:\Users\saina\Videos\YT Automation\output\video_9.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_9_thumbnail.png','jCkJuDYc4KA','uploaded','''int'' object has no attribute ''execute''','2026-08-11 11:14:15','2026-08-11T11:36:58.200778+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_9_manifest.json');
INSERT INTO "videos" VALUES(10,NULL,NULL,'mystery','short','A','The voice mail That Calls Itself at 3:17 AM | Night Loom','The last voice mail my aunt left doesn''t contain her voice.','I don''t know if my aunt was the one who left that message anymore. But the sound is learning my name.','Tell me in the comments what you think that sound is — before the next call comes.','{"title": "The voice mail That Calls Itself at 3:17 AM | Night Loom", "hook_line": "The last voice mail my aunt left doesn''t contain her voice.", "intro_line": "Welcome to Night Loom, where this one has kept me awake since I heard it.", "scenes": [{"narration": "The call came from inside her bedroom, which was locked from the inside. The message buries a sound under static, something like wet pages turning, or a breath that never arrives.", "visual_prompt": "Police light flickering through blinds, an old phone on a nightstand, a glowing audio waveform frozen on a screen."}, {"narration": "I asked the carrier to trace it. They said the number didn''t exist. That night, under the attic floorboard, I found a second phone wrapped in a black towel, its battery dated for a week after today.", "visual_prompt": "Flashlight beam pulling up a loose attic floorboard, a hand lifting a towel-wrapped object, a camera close-up of a battery with an impossible future date."}, {"narration": "I pressed the only button. The voice that answered spoke my name the way I say it, not the way anyone else does. It said: stop digging before the sound learns your rhythm. Then every window in the house released at once.", "visual_prompt": "Dark room, a phone held to a person''s ear, eyes widening, curtains snapping sideways as multiple windows bang open at the same time."}, {"narration": "I keep that phone in a drawer with the battery removed. Twice a year at 3:17 AM, it calls my old cell from itself. I answer only when it lets me. The whisper at the end gets a little slower every time.", "visual_prompt": "A clock showing 3:17 AM, a drawer sliding open, a phone screen lighting up with no caller ID, subtle distortion creeping across the image."}], "ending_line": "I don''t know if my aunt was the one who left that message anymore. But the sound is learning my name.", "cta": "Tell me in the comments what you think that sound is \u2014 before the next call comes.", "youtube_description": "A woman receives a voice mail from her aunt''s phone, but the voice on it isn''t her aunt''s. What follows is a phone that shouldn''t exist, calls at 3:17 AM, and a sound that seems to learn its listener. Subscribe to Night Loom for quieter mysteries that stay with you.", "tags": ["Night Loom", "mystery voice mail", "strange phone call", "true mystery story", "unexplained audio", "3:17 AM", "horror mystery", "who was calling"]}','2657dc0d30c823b0','C:\Users\saina\Videos\YT Automation\assets\audio\video_10.mp3','C:\Users\saina\Videos\YT Automation\output\video_10.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_10_thumbnail.png','IAMC2XSUpqw','uploaded',NULL,'2026-08-11 11:43:43','2026-08-11T11:55:44.572878+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_10_manifest.json');
INSERT INTO "videos" VALUES(11,NULL,NULL,'horror','short','A','My Phone Called Itself and Spoke in My Voice','My phone just called itself from my own pocket, and when I answered, my own voice said, ''don''t open it.''','I still have that phone, but I keep it in a drawer. Sometimes it calls itself. I never answer.','If something has ever called you from your own number, tell me in the comments — and subscribe to Night Loom for more stories like this.','{"title": "My Phone Called Itself and Spoke in My Voice", "hook_line": "My phone just called itself from my own pocket, and when I answered, my own voice said, ''don''t open it.''", "intro_line": "You''re watching Night Loom, and I should have listened.", "scenes": [{"narration": "I was alone in the apartment. The call lasted two seconds, then silence. When I checked, there was no incoming call, no history, no voice mail \u2014 just that short warning still hanging in the air.", "visual_prompt": "A person alone in a dim apartment, staring at their phone screen, the contact name matching their own name."}, {"narration": "I made sure every door and window was locked. That''s when the phone buzzed with a text from my own number. It was a photo \u2014 taken from the other side of my front door, looking through the peephole at my eye.", "visual_prompt": "A phone screen showing a horrifying photo: an eye seen from outside the peephole, the hallway slightly distorted."}, {"narration": "I stepped back. The doorbell rang. Another call from my own name. I answered, and my voice \u2014 slower, softer \u2014 said, ''it''s cold out here. Open it.''", "visual_prompt": "Close-up of a phone with an incoming call labeled with the owner''s name, while an echoing doorbell fills the hallway."}, {"narration": "I didn''t. I locked the deadbolt again and moved away. Behind me, the bathroom door, which was closed a minute ago, stood open. And from inside, that same voice whispered, ''wrong door.''", "visual_prompt": "A bathroom doorway standing open into darkness, with a faint figure barely visible inside."}], "ending_line": "I still have that phone, but I keep it in a drawer. Sometimes it calls itself. I never answer.", "cta": "If something has ever called you from your own number, tell me in the comments \u2014 and subscribe to Night Loom for more stories like this.", "youtube_description": "A late-night call from your own number is alarming enough, but what waited on the other end of the line followed me home. This is the story of precisely that night. Subscribe to Night Loom for more stories that stay with you long after the screen goes dark.", "tags": ["Horror story", "Night Loom", "Scary stories", "Phone horror", "Unsettling stories", "Creepy caller", "Paranormal experience", "Late night horror"]}','fb14f041b7ecf1cd','C:\Users\saina\Videos\YT Automation\assets\audio\video_11.mp3','C:\Users\saina\Videos\YT Automation\output\video_11.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_11_thumbnail.png','BTf3Egj-c44','uploaded',NULL,'2026-08-11 15:54:46','2026-08-11T16:09:09.140365+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_11_manifest.json');
INSERT INTO "videos" VALUES(12,NULL,NULL,'facts','long_continuous','A','The Immortal Jellyfish and Other Facts That Sound False','There is a jellyfish that can live forever, and the mechanism behind it makes a mockery of everything we think we know about growing old.','If any of this sounds like fiction, remember: reality has been running these experiments far longer than we have been telling stories.','Which fact rewired your brain the most? Tell me in the comments, and if you want more strange true stories, subscribe to Night Loom.','{"title": "The Immortal Jellyfish and Other Facts That Sound False", "hook_line": "There is a jellyfish that can live forever, and the mechanism behind it makes a mockery of everything we think we know about growing old.", "intro_line": "Welcome to Night Loom, where we pull the strangest true stories out of the dark and hold them up to the light.", "scenes": [{"narration": "Turritopsis dohrnii is the full name, and it is only about half a centimeter across. When this jellyfish reaches its adult form, it can push a hidden reset button. Instead of dying after reproducing, it shrinks back to its earliest stage, attaches itself to a surface as a polyp, and then grows up all over again. It is a process that should not be possible. Mature cells are normally locked into their identity \u2014 a nerve cell stays a nerve cell, a muscle cell stays a muscle cell. But Turritopsis can transform its specialized cells back into a blank, stem-cell-like state. Scientists call this transdifferentiation, which is a polite way of saying it rewinds its own biology. In a laboratory, researchers have seen it repeat this cycle again and again. It is effectively immortal, not in a mystical sense, but in a cellular one. That does not mean it cannot be eaten by a fish or destroyed by disease. It means that, given safe conditions, it does not seem to age. It has found a loophole in time. The rest of us get a lifetime. It gets a loop.", "visual_prompt": "Close-up of a tiny translucent jellyfish reversing into a polyp, glowing blue"}, {"narration": "There is an animal that edits its own genetic instructions in real time, and it has eight arms. Octopuses rewrite their RNA in ways we are only beginning to understand. Most species pass mutations down through generations; that is evolution''s slow grind. Octopuses, however, can alter the copies being made from DNA right inside their bodies. In cold water, they edit proteins in their neurons so that signals still fire properly. Their genetic text stays the same, but the footnotes change. Some researchers call this a kind of biological software update, and the temperature-based edits have been measured. One species, the Antarctic octopus, carries tens of thousands of such edits. The octopus is also built strangely: roughly half its nerve cells sit not in a central brain but in its arms. Each arm can taste, touch, and even make decisions almost on its own. So when an octopus adapts to a changing ocean, it is not waiting for future generations to fix the problem. It is patching itself in real time.", "visual_prompt": "Octopus in cold water with superimposed genetic code strands and neural sparks"}, {"narration": "There is a brainless organism that can solve mazes. It is called Physarum polycephalum, and informally it is known as a slime mold, which is misleading because it is not a mold and not a fungus. It is a single cell that can stitch itself into sprawling networks. In one experiment, researchers placed it at an entrance to a maze with a food source at the other end. The slime mold extended its tendrils along every possible route, retreated from dead ends, and eventually settled on the shortest path. That is decision-making without a brain. The most famous demonstration repeated the trick on a larger scale: city locations were represented by oat flakes, and the network the slime mold grew almost matched the Tokyo rail system, which took human engineers decades to optimize. A single-celled organism did it in days. It does not see the puzzle. It senses gradients and patterns, but somehow that is enough to solve a problem that seems to demand planning, memory, and foresight.", "visual_prompt": "Time-lapse of yellow slime mold network growing across a printed maze and Tokyo map"}, {"narration": "Trees have a secret social network, and it runs underground. Around their root tips, trees form partnerships with mycorrhizal fungi, which stretch into the soil like millions of tiny threads. These threads link separate trees into a shared network. Carbon moves from one tree to another through the fungal pipelines, and this has been measured with isotope labels. In a forest in British Columbia, researchers found that older trees, sometimes called mother trees, route carbon to their kin, especially young seedlings growing in dim light. The network also sends alarms. When a tree is attacked by insects, it can push warning chemicals to neighbors through the same fungal connections, giving them time to raise their defenses. Some of this communication is chemical, some electrical, and almost all of it is invisible. The forest floor is less like a collection of separate individuals and more like one slow, wide intelligence occurring underfoot.", "visual_prompt": "Forest underground view of roots connected by glowing fungal threads"}, {"narration": "Honeybees understand the concept of zero, an abstraction that human societies took centuries to accept as a real number. To test this, researchers taught bees to choose the image with fewer shapes by rewarding them with sugar. Most bees learned the rule. Then came the critical moment: a card with one shape versus a completely blank card. If the bees were only comparing quantities, they should have seen the blank as nothing and ignored it. Instead, they flew to the blank card. They understood that the absence of a shape is still an amount \u2014 zero. That may not sound radical, but zero was a hard philosophical idea. A symbol for nothing appeared in human records long after counting did. A honeybee, with about one million neurons, can make that leap in almost no training. It is one of the smallest brains known to handle an abstraction we once called impossible.", "visual_prompt": "Honeybee flying toward a blank white card next to a card with one black shape"}, {"narration": "The most complex eyes in the animal kingdom belong to an animal that uses them for a punch. The mantis shrimp is not a shrimp, and it does not behave politely. Its eyes contain up to sixteen kinds of color receptive cells. Human eyes contain three. It can see ultraviolet, and it is the only animal known to detect circularly polarized light. The eyes sit on independent stalks that roll, tilt, and track prey without the head moving. A band across the middle of each eye gives the mantis shrimp trinocular depth perception, meaning each eye can judge distance on its own. With that visual arsenal, it locks onto a target and strikes with a club-shaped appendage moving so fast that it cavitates water, producing flashes of heat and light. The mantis shrimp does not perceive the world as a refined painting. It sees it as a targeting system, and it needs only the split second before the strike.", "visual_prompt": "Hyper-saturated macro shot of a mantis shrimp eye with spectral reflections"}, {"narration": "The animal that looks like a biological prank has a sixth sense we once thought impossible. The platypus lays eggs like a reptile, produces venom like a snake, and has a bill like a duck. But inside that bill are electro receptors \u2014 thousands of nerve endings that detect the weak electric fields given off by living muscles. When a platypus dives, it closes its eyes, ears, and nostrils completely. It hunts with a different channel. It swims with its bill sweeping back and forth, picking up the tiny electrical shadows of shrimp and worms buried in the mud. This is not a mystical gift; it is a physical sense, and it shocked biology. No other mammal was known to do this at the time. The platypus was so bizarre that early European scientists thought it was a taxidermist''s hoax. It turned out the hoax was on them \u2014 a mammal navigating by electricity.", "visual_prompt": "Platypus swimming underwater with electric field lines radiating from its bill"}, {"narration": "The invisible life form carrying the planet''s atmosphere is a bacterium with a name almost nobody knows. Prochlorococcus was discovered in 1985, hidden in the open ocean, and it is thought to be the smallest and most abundant photosynthetic organism on Earth. It is so small that around a million individual cells can fit in one drop of seawater. Yet collectively, it produces roughly ten percent of all the oxygen on Earth. That means for about one of every ten breaths you take, you owe it to a living cell the size of nothing. The reason it stayed hidden so long is that it uses an unusual kind of chlorophyll that did not match the instruments scientists used. It was not invented. It was encountered. And it is everywhere. Whole layers of ocean are stained with it, and it has adapted to everything from sunlit surface waters to the dim lower edge of the twilight zone. The blue planet is, underneath, a green one \u2014 and we still do not fully understand it.", "visual_prompt": "Ocean surface with a drop of seawater lit up showing microscopic Prochlorococcus cells glowing green"}, {"narration": "There is an ant that knows math you did not know when you got out of bed. Desert ants walk across barren salt flats that look identical in every direction, then turn around and run straight home to a nest entrance the size of a coin. They do it with an internal step counter. In classic experiments, scientists made tiny stilts for ants and also shortened the legs of other ants. The ants on stilts overshot the nest by exactly the distance their longer strides would predict. The ants with shortened legs undershot. Neither group could see the nest, but their legs had measured the journey. On top of that, each step''s direction comes from polarized light in the sky, which they read with specialized receptors in their eyes. Combine distance and direction, and you have a natural navigation system. It is not intelligence in the human sense. It is a precise biological instrument, working flawlessly at a scale we often overlook.", "visual_prompt": "Desert ants walking in sand, one on tiny stilts, with angular lines representing polarized light in the sky"}, {"narration": "There is an animal that regenerates parts of its brain without trying. The axolotl is a salamander that keeps its juvenile features for its whole life, including frilly external gills. But the stranger thing is its ability to rebuild. If an axolotl loses a limb, the wound closes, cells gather, and a new limb grows back with bones, muscles, nerves, and skin. It does not stop there. It can regenerate parts of its heart, its spinal cord, and even portions of its brain. And it does all of this without forming scar tissue. Mammals heal wounds by patching them with fibrous scars; the axolotl somehow remembers the original design and continues building it. Researchers are studying its cells in hopes of understanding how human injuries might be repaired one day. The axolotl is not a magical creature. It is a biological instruction manual we are only beginning to read.", "visual_prompt": "Axolotl in a bright aquarium with glowing cells forming a regenerating limb"}, {"narration": "An electric eel does not just shock. It uses electricity like a remote control. Hidden inside its body are three electric organs that fire together to create powerful fields. At low voltage, the eel scans the water like a radar. At high voltage, it stuns prey. But the strangest trick is what researchers discovered by accident: when the eel encounters a hiding fish, it delivers a rapid double pulse that forces the prey''s own nerves to fire involuntarily. The fish''s muscles twitch, and that twitch reveals its exact location. In other words, the eel is not only detecting prey; it is commanding the prey''s body to announce itself. Then, with a second type of signal, it can force the same fish into an escape response that sends it straight into the eel''s mouth. The eel turned another animal''s nervous system into a tool.", "visual_prompt": "Electric eel in dark water with blue electric arcs tracing from its body toward a fish"}, {"narration": "You are closer in time to Tyrannosaurus rex than Tyrannosaurus rex was to Stegosaurus. The last Stegosaurus walked the earth about one hundred and fifty million years ago. The first Tyrannosaurus rex appeared about sixty-eight million years ago. That is an eighty-million-year gap. Tyrannosaurus rex and humans, by comparison, are separated by only about sixty-six million years. So a Stegosaurus would have felt the last of its kind vanish long before anything resembling a T. rex ever existed. The deep past is not one flat dinosaur era. It is a series of separate worlds stacked one on top of another, with gaps so vast that our own distance from a T. rex seems short by comparison. When we say that dinosaurs ruled for hundreds of millions of years, we are talking about dynasties that never met.", "visual_prompt": "Timeline graphic showing Stegosaurus, a vast empty gap, then T. rex, then a smaller gap to a human figure"}], "ending_line": "If any of this sounds like fiction, remember: reality has been running these experiments far longer than we have been telling stories.", "cta": "Which fact rewired your brain the most? Tell me in the comments, and if you want more strange true stories, subscribe to Night Loom.", "youtube_description": "Watch to the end for true facts that sound like fiction, starting with a jellyfish that rewinds its own life. From brains on eight arms to invisible bacteria that make your oxygen, these are the weirdest realities in the natural world. If you love being surprised by what''s real, subscribe to Night Loom for more.", "tags": ["immortal jellyfish", "true facts", "nature facts", "octopus intelligence", "slime mold", "axolotl regeneration", "electric eel", "Night Loom"]}','62ffd0df33fa5539','C:\Users\saina\Videos\YT Automation\assets\audio\video_12.mp3','C:\Users\saina\Videos\YT Automation\output\video_12.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_12_thumbnail.png','bfeuyIFJvHw','uploaded','SadTalker inference failed with exit code 1.','2026-08-11 16:25:25','2026-08-11T18:11:01.859651+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_12_manifest.json');
INSERT INTO "videos" VALUES(13,NULL,NULL,'motivational','short','A','I Ruined My Best Work One Hour Before It Was Finished','I ruined my best work one hour before it was finished.','I glued the piece, clamped it, and left the seam visible. That table sits in her house now. Finish is not the absence of damage; it''s what you do after.','If you want one grounded push every day, subscribe to Night Loom.','{"title": "I Ruined My Best Work One Hour Before It Was Finished", "hook_line": "I ruined my best work one hour before it was finished.", "intro_line": "Here on Night Loom, this one taught me something about quitting.", "scenes": [{"narration": "Eleven months of weekends in a rented garage. A walnut table, every joint cut by hand, no screws. I built it for my mother.", "visual_prompt": "Hands planing a walnut table in a dim garage, sawdust in the air."}, {"narration": "On the final pass with the sander, I pressed too hard. The top corner splintered and peeled away like bark. I stood holding the broken piece, and the garage suddenly felt too small.", "visual_prompt": "Close-up of a sander lifting from a wood corner as splinters peel away."}, {"narration": "I threw the sander across the floor. I packed my tools. I told myself I could start again in the spring. Then I sat in my car, and for twenty minutes my hands refused to turn the key.", "visual_prompt": "A man sitting in a dark car, keys in hand, garage door half open."}, {"narration": "What stopped me wasn''t patience or hope. It was knowing the break was already there. I had two choices: hide it, or let it be part of the work.", "visual_prompt": "Close-up of a splintered wood corner, then hands picking up the broken piece."}], "ending_line": "I glued the piece, clamped it, and left the seam visible. That table sits in her house now. Finish is not the absence of damage; it''s what you do after.", "cta": "If you want one grounded push every day, subscribe to Night Loom.", "youtube_description": "Eleven months of work, one bad pass with a sander, and a decision that changed how I finish things. This short, true story is about what happens after you ruin your best work \u2014 and why the scar might be the point. Subscribe to Night Loom for one grounded story every day.", "tags": ["motivational story", "finishing what you start", "overcoming mistakes", "craftsmanship", "personal growth", "discipline", "Night Loom", "true story"]}','5f284dd9710865e5','C:\Users\saina\Videos\YT Automation\assets\audio\video_13.mp3','C:\Users\saina\Videos\YT Automation\output\video_13.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_13_thumbnail.png','HYPDSkZSqjw','uploaded',NULL,'2026-08-11 18:17:50','2026-08-11T18:28:59.694701+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_13_manifest.json');
INSERT INTO "videos" VALUES(14,NULL,NULL,'mystery','short','A','The Distress Call From a Ship That Sank in 1962','The distress call came from a ship that had been dead for forty years.','The logbook''s last entry, in capital letters: ''They couldn''t see the shore. They only saw me. I left it on.''','What do you think the light really was? Drop a theory below and subscribe before the next tape surfaces.','{"title": "The Distress Call From a Ship That Sank in 1962", "hook_line": "The distress call came from a ship that had been dead for forty years.", "intro_line": "You''re watching Night Loom, and this one came off a tape I wasn''t supposed to find.", "scenes": [{"narration": "Inside a 2003 logbook at the old Point Loomis radio station, the operator transcribed one transmission and underlined it three times. Call sign: Meridian. Then he wrote: I know this ship. I know this night.", "visual_prompt": "Close-up of an open logbook, pencil underlining a call sign, old desk and lamp."}, {"narration": "The Meridian went down in 1962, all souls lost. The official last message was garbled, but the radioman''s diary said the crew kept repeating one phrase: ''We see your lights.'' The station log that night said there was no light on the bluff.", "visual_prompt": "Aged maritime files and a handwritten diary, a storm-lit ship in the background."}, {"narration": "The 2003 recording begins with static. Then a man says, ''It''s still there.'' A woman answers, ''Then we''re not lost. We see your lights.'' The tape ends with a time stamp\u20143:07 AM, the same minute the original transmission died.", "visual_prompt": "Old cassette player with reels turning, sound waves shown as faint lines."}, {"narration": "I drove to the bluff. There is no lighthouse. There never was. But there is an abandoned telephone line and, at the end of it, a solar-powered beacon installed in 2003\u2014the same week as the recording.", "visual_prompt": "Aerial view from bluff to dark sea, a narrow beam of light hitting water, wreck outline under waves."}, {"narration": "Its beam, through one old radio room window, crosses the exact patch of sea where the Meridian''s wreck lies. The ship didn''t see the future. It saw the correct place. They were only waiting for someone to leave the light on.", "visual_prompt": "Light beam through a rectangular window, reaching a marked spot on an old map of the sea with a shipwreck symbol."}], "ending_line": "The logbook''s last entry, in capital letters: ''They couldn''t see the shore. They only saw me. I left it on.''", "cta": "What do you think the light really was? Drop a theory below and subscribe before the next tape surfaces.", "youtube_description": "A radio operator in 2003 logged a distress call from a ship that sank in 1962. This is the paper trail he left behind. Subscribe to Night Loom for more mysteries that have no right to exist.", "tags": ["Night Loom", "mystery", "unsolved mystery", "radio call", "ghost ship", "true story", "unexplained", "distress call"]}','17aa7a79141c242d','C:\Users\saina\Videos\YT Automation\assets\audio\video_14.mp3','C:\Users\saina\Videos\YT Automation\output\video_14.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_14_thumbnail.png','ca0idCDybRM','uploaded',NULL,'2026-08-12 03:42:03','2026-08-12T03:55:10.057197+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_14_manifest.json');
INSERT INTO "videos" VALUES(15,NULL,NULL,'facts','short','A','The Jellyfish That Can Reverse Its Own Age','There’s a jellyfish that doesn’t age like we do. When life gets dangerous, it can age backward.','So somewhere in the sea, one jellyfish might be living through its own past right now.','What surprised you most—the age reversal or the catch? Let me know in the comments, and subscribe to Night Loom for more true stories from the edges of science.','{"title": "The Jellyfish That Can Reverse Its Own Age", "hook_line": "There\u2019s a jellyfish that doesn\u2019t age like we do. When life gets dangerous, it can age backward.", "intro_line": "Welcome to Night Loom, where the strangest facts in nature get a closer look.", "scenes": [{"narration": "Scientists found this tiny animal in the Mediterranean, and in a lab dish, they watched it face starvation. They expected it to die.", "visual_prompt": "A tiny translucent jellyfish in a petri dish, seen through a microscope while researchers observe."}, {"narration": "Instead, its body didn\u2019t break down. Its tentacles folded inward, it settled onto the glass, and it became a polyp\u2014a much younger stage in its life.", "visual_prompt": "Time-lapse of a jellyfish contracting, attaching to glass, and morphing into a polyp."}, {"narration": "Then that polyp budded and grew into a fully formed jellyfish again. The same individual had reversed its life cycle, not once, but as many times as needed.", "visual_prompt": "Time-lapse of the polyp sprouting and growing into a new adult jellyfish underwater."}, {"narration": "This is Turritopsis dohrnii, the so-called immortal jellyfish. It can\u2019t die of old age, but it can still be eaten, so immortality is a loophole, not a guarantee.", "visual_prompt": "Split screen: the immortal jellyfish drifting in open water, then a fish closing in to eat it."}], "ending_line": "So somewhere in the sea, one jellyfish might be living through its own past right now.", "cta": "What surprised you most\u2014the age reversal or the catch? Let me know in the comments, and subscribe to Night Loom for more true stories from the edges of science.", "youtube_description": "There\u2019s a jellyfish that can turn back its biological clock. In this video, we explore the science behind Turritopsis dohrnii and what \u201cimmortal\u201d really means for this tiny sea creature. If you enjoy true stories that sound impossible, subscribe to Night Loom.", "tags": ["immortal jellyfish", "Turritopsis dohrnii", "facts", "nature facts", "biology", "age reversal", "Night Loom", "ocean mysteries"]}','80770abce6886400','C:\Users\saina\Videos\YT Automation\assets\audio\video_15.mp3','C:\Users\saina\Videos\YT Automation\output\video_15.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_15_thumbnail.png','mk5JH5KjeRM','uploaded',NULL,'2026-08-12 04:05:17','2026-08-12T04:29:00.059908+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_15_manifest.json');
INSERT INTO "videos" VALUES(16,NULL,NULL,'motivational','short','A','The Best Advice Came From a Stranger at 2 A.M. | Night Loom','The best advice I ever got came from a man swimming laps at 2 A.M.','That conversation cost me nothing. Not taking it would have cost me everything.','If this landed, subscribe — I post a story like this every day.','{"title": "The Best Advice Came From a Stranger at 2 A.M. | Night Loom", "hook_line": "The best advice I ever got came from a man swimming laps at 2 A.M.", "intro_line": "You''re watching Night Loom \u2014 tonight''s story starts at a motel front desk.", "scenes": [{"narration": "I was 24, $47,000 in debt, and my job was to sit behind a desk and watch the parking lot until sunrise.", "visual_prompt": "Night shot of a dim, empty motel parking lot seen through a front desk window; a young clerk sits alone"}, {"narration": "Every night at 2 A.M., the same guest would swim laps in the pool. I assumed he was rich, retired, at peace. Then one night he stopped at the front desk.", "visual_prompt": "An elderly man doing slow laps in a glowing motel pool at night, then walking toward the office"}, {"narration": "He told me he''d spent 40 years as a lawyer and hated every morning of it. His doctor said his heart couldn''t take the stress anymore. Then he looked at me and said, ''You''re still young enough to be poor at something you love.''", "visual_prompt": "Close-up of the older man''s tired face across the counter, speaking; the clerk listens, hands still"}, {"narration": "I quit two weeks later. It took seven years to build what I have now, but I haven''t had one morning that felt like drowning since.", "visual_prompt": "The clerk packing a small bag, handing in a key, then a time-lapse of years: notebooks, toolboxes, a small desk becoming a studio"}], "ending_line": "That conversation cost me nothing. Not taking it would have cost me everything.", "cta": "If this landed, subscribe \u2014 I post a story like this every day.", "youtube_description": "A stranger in a motel pool told me the truth I needed to hear at 24. This is the story of how one conversation changed my direction for good. Subscribe to Night Loom for daily motivation grounded in real stories.", "tags": ["Night Loom", "motivational story", "life advice", "2 A.M. conversation", "real life motivation", "career change", "daily motivation"]}','5fac78b61c4e0d8c','C:\Users\saina\Videos\YT Automation\assets\audio\video_16.mp3','C:\Users\saina\Videos\YT Automation\output\video_16.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_16_thumbnail.png','h70ApSxegAI','uploaded',NULL,'2026-08-12 04:08:22','2026-08-12T04:17:56.259129+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_16_manifest.json');
INSERT INTO "videos" VALUES(17,1,1,'horror','long_continuous','A','The Keeper''s Last Entry: The Light Must Never Stop','The last thing the lighthouse keeper said to me was not a warning; it was an apology.','The sea does not take politely; it borrows, and one day it comes to collect—but some of us spend our whole lives trying not to be the debt.','If you have a place like that—a quiet stretch of water, an old tower, a light you can''t trust—I want to hear it. Leave it in the comments, and don''t forget to subscribe to Night Loom for more stories that shouldn''t be told twice.','{"title": "The Keeper''s Last Entry: The Light Must Never Stop", "hook_line": "The last thing the lighthouse keeper said to me was not a warning; it was an apology.", "intro_line": "You''re watching Night Loom, and this is the story of how I learned that some beams are not meant to touch the water.", "scenes": [{"narration": "I know that because I went to the lighthouse after he vanished. The ferryman wouldn''t come any closer than the old jetty. He kept the engine running, and he told me that Elias had been a good man, but the sea had been chewing on him for years. I asked what that meant. He just looked at the tower and said, ''The last time I brought his supplies out, he met me on the rocks. He wasn''t wearing boots. His feet were wet, and the tide was going out. He said: you should not have come. But he was the one who asked me to come. That''s the part I can''t fold into my head.'' The ferryman pushed my crate onto the dock and left before I could ask who, exactly, had asked him to come. The phrase stayed with me as I climbed the path. It wasn''t a question of what I''d find; it was a question of who had invited me. The tower sat against the sky like a bone with the flesh picked clean. I should have gone home then. The sky was the color of old tin, and the gulls had stopped crying.", "visual_prompt": "Gloomy coastal morning, a small boat idling beside a crumbling stone jetty; a lone narrator with a crate watches the tower on the headland."}, {"narration": "The lighthouse door was unlocked. Inside, the air was cold and dense, like the inside of a mouth. Every surface was salted white. Elias had left his breakfast on the table\u2014tea with a skin, bread with a single bite missing. The logbook lay open under the window. The last entry was dated three weeks after the ferryman''s final supply run. It said: The lens must keep moving. If the beam rests on the water for more than three seconds, something below notices it can see. Keep the shaft greased. Do not stand in the light when it comes around. I thought it was a joke, the kind a lonely man writes to keep himself company. Then I turned the page. There were only dashes. But under the dashes, written so hard the page had torn, were the words: It already knows the pattern. It is learning to count.", "visual_prompt": "Dim lighthouse room with pale salt film; open logbook on wooden table; a cloth is missing from a half-eaten meal."}, {"narration": "I told myself Elias was just unwell. He had been alone too long, and the sea does strange arithmetic to a person''s mind. I was there to retrieve the records before the tower was automated, so I started with the storage room. I found a strongbox under a tarp. It contained a hundred years of keeper notes, all stitched together with twine. The oldest entries, from the builders in 1923, were not about maintenance. They were about trials. Before the present light was installed, the old lamp had been a simple fixed lens, a steady flame behind a pane. During the first year, three ships wrecked on perfectly clear nights. The crews all came ashore claiming the light had stopped moving. But a fixed light never moves. So why did they all say the same thing? They said the light blinked. They said the sea underneath it turned pale and solid, like a throat swallowing. The builders eventually designed the revolving lens. They didn''t call it a navigational light in the blueprints. They called it a blindfold. The last page of that bundle was a letter, brittle as a wasp''s wing. The first keeper had written to the commissioner: ''The thing has fed once. It will not unlearn the taste. Do not let them install a steady light here, no matter what the shipping board says. A moving light is a broom. A still light is a hand.'' I put the letter back, careful not to tear it. The words were not the ramblings of a madman. They were advice.", "visual_prompt": "Narrator kneeling beside an open storage room; hands lifting a bundle of old, salt-stained papers tied with twine; distant sound of wind through cracks."}, {"narration": "At dusk I went up to the lantern room. The lens was a brass-and-glass hive, as tall as a man, with a lamp at its center. It turned slowly, one complete sweep every nine seconds. The motor hummed, but underneath that hum I heard a dragging sound, like a wet rope being pulled through a pulley. I checked the drive shaft. The bearings were coated in a dark grease that looked like tar. It was not the right kind of grease; it smelled faintly of iodine and copper. I cleaned it, re-packed it with the proper compound from the supply box, and tested the mechanism. It moved smoothly. I should have felt proud. Instead I felt as if I had oiled a lock that was better left rusted. At sundown, I saw the water. There was a ship beyond the reef, under full sail in a dead calm. Far too slow to be real. Its windows were lit, and the light from the tower passed over it without touching it. Then the beam moved on, and the ship was gone. My radio made a low, gurgling sound, not a voice, not static\u2014something trying to form a word with wet lungs. I switched it off, and for a moment the room was so quiet I could hear my pulse. The lantern had completed another sweep, but the timing was wrong. There was a pause at the end of the turn, a tiny held breath before the beam began its return. I had packed the bearings properly. I had not packed them perfectly. Some part of me already knew the difference.", "visual_prompt": "Tall brass Fresnel lens rotating in darkness, throwing angular patterns; a distant impossible sailing ship in the silver-blue twilight, windows glowing."}, {"narration": "I called the coastguard on the marine radio. Through a screen of static, I heard a man''s voice, tired and patient. He said the lighthouse was automated and serviced by a maintenance crew once a month. I told him I was there to collect the archives. He was quiet for a moment. Then he said, ''There''s no archive order for that tower. The last request for a crew was six years ago. Who signed the work order you''re carrying?'' I looked at the paper in my hand. The signature was Elias K\u2014, the missing keeper. But the initials were wrong. Elias wrote his name in a neat, square hand. This signature was rounded, almost watery, spaced too wide. I told the coastguard it didn''t matter, I would check the records myself and leave before dark. The man on the radio said, ''If you see a light inside the water, do not let the beam stop. Let it keep moving. Whatever you do, let it keep moving.'' The line went dead before I could ask how he knew that.", "visual_prompt": "Close-up of a radio microphone in a dim room, call sign plate taped to the panel; a hand holding a paper with a strange, washed-out signature."}, {"narration": "The work order made no sense. I walked around the tower outside, checking the waterline, and I found a second door, low in the wall, hidden under a coil of rusted chain. It was not in the blueprints. It was made of iron, and it felt cold even in the late light. I wedged it open. A narrow stair went down into dark water. Not seawater\u2014dark, still water that had no smell of salt. The walls were humid and covered with a substance that looked like wax. I called out Elias''s name. My voice came back to me in pieces, sometimes after a second, sometimes after three. And in one echo, I heard not my own voice but a phrase, worn thin: ''Keep it moving.'' It could have been a trick of the stair. It could have been the house holding sound in its stone. I got out, pulled the iron door shut, and promised myself I would not open it again. It was the last promise I kept that night.", "visual_prompt": "Iron door half open in the tower''s sea wall; a narrow stair descending into black water; faint wet shine on stone stairs."}, {"narration": "I did not leave. That is the part I have to live with. I told myself it was rain coming in through a window; I told myself the lower gear was worn. But the truth is, I stayed because the lens had started to slow. Each sweep took a little longer. The motor was not losing power. I could see it\u2014the huge brass ring was catching on something, the way a hand catches on a coat sleeve. I went down to the generator and found the source. A coil of rope was jammed in the drive chain. It was not old rope. It was wet, and it was still twitching. I pulled it free. That was when I heard the knock. It came from below, from the sealed room at the base of the tower, the one room no blueprint showed. Three slow knocks. Then a pause. Then two knocks, as if answering me. I counted them. Three. Two. The beam overhead had stopped. I could feel the absence of motion in the floor, the sudden weight of a mechanism waiting. I looked out the small porthole at the sea. The water was still\u2014too still, like black glass. And under the surface, a pale gold light was opening, exactly where the beam should have rested.", "visual_prompt": "Narrator in a cramped generator room, tugging a wet rope from a drive chain; through a small porthole, the sea is glass-like with an amber glow beneath."}, {"narration": "I scrambled up the spiral stairs. The lantern room was silent. The great lens sat unmoving, and a single blade of light pointed out over the water, a road of pale fire that ended at something that was rising. I threw the motor switch. Nothing. I threw it again. The motor whined, then bound. And as I stood there, the beam stayed fixed, and the threshold between the tower and the sea became terribly thin. The glow in the water did not rise to the surface. It moved along the beam, like a pulse along a thread. It came closer, and closer, and the light in the lantern room began to bend toward it, as if the beam were being reeled in from the far end. That was when I saw Elias. He was in the water, standing upright on the seabed, or what appeared to be standing. His face was pale under the boat-light, and his mouth was open. He said, in a voice that did not travel through air, ''I''m sorry. I tried to keep it from learning. But you greased the shaft. You made it smooth. It counted the pauses. It knows the rhythm now. Let it come. When it reaches the glass, you will see what it wants.''", "visual_prompt": "Top of the lighthouse: static lens throwing one long beam over a black sea; below, a luminous shape moving along the beam toward the tower; a pale figure submerged in the water."}, {"narration": "I remember the taste of copper in my throat. I remember the heat from the lamp suddenly doubling, the glass panes beginning to sweat. And I understood, in that hollow place where fear lives, that the beam was not a signal. It was a hand reaching down. Elias had not been keeping the light moving to protect the ships. He had been keeping it moving so that whatever dwelt in the dark below never received a steady hand to take. But I had stopped the motion. I had answered. There was only one thing left to do. I pulled my raincoat over my head, and I swung the iron tool the way a man swings a hammer at a chain. I broke the lens. The light went out. The sudden dark was enormous and wet. Then the silence was broken by a sound like a sea creature drawing a breath, and the glow in the water collapsed, spiraling downward until it was gone. Something on the rocks below made a scraping sound. Not footsteps. More like the sound a heavy anchor makes when it is dragged across stone.", "visual_prompt": "Narrator with a steel bar shattering the Fresnel lens; glass explodes, the light dies, and a huge underwater glow collapses into darkness; rocks below faintly visible."}, {"narration": "I was found the next morning on the lower rocks, covered in salt and glass dust. The tower was dark, and for the first night in a hundred years, the headland had no light. The coastguard called it a generator failure. The harbor commission called it neglect. I called it an abomination ending\u2014but I never said that out loud. Before I left, I went down to the sealed room in the base. The door was open. Inside, there was no machinery. There was only a pool of brackish water in the stone floor, perfectly round, and at the bottom of that pool, a single brass key. The key was not old. The key was still warm. I did not take it. I did not even look at it for more than a second, because around its head was a circle of words, stamped into the metal, small enough that I had to lean close to read them: ''If the light finds you, thank it. It has brought a guest.''", "visual_prompt": "Dawn mist around a dark lighthouse; narrator exhausted on rocks, then descending to a small round pool in a stone room; a warm brass key glinting at the bottom."}, {"narration": "I don''t know if the creature is gone. I don''t know if it ever left. Sometimes, driving along the coast at night, I see a beam of light sweeping over the water from a lighthouse that is supposed to be abandoned. And I slow down. I watch. The beam always moves. It moves in a perfect rhythm, one sweep every nine seconds, never hesitating, never slowing. But sometimes the light is too steady, too patient. It does not feel like a warning. It feels like something waiting for me to stop and look. I have not stopped. I do not plan to. But the last thing Elias said to me, before the light went out, was not a curse. It was an apology. And now I think I know what he was apologizing for. He was sorry that I would spend the rest of my life watching water, wondering if what I saw beneath it was a reflection of something above\u2014or something above was the reflection of what is below.", "visual_prompt": "Night drive along a coastal road; a distant lighthouse beam sweeps rhythmically across dark water; the driver''s eyes in the rear view mirror, haunted."}], "ending_line": "The sea does not take politely; it borrows, and one day it comes to collect\u2014but some of us spend our whole lives trying not to be the debt.", "cta": "If you have a place like that\u2014a quiet stretch of water, an old tower, a light you can''t trust\u2014I want to hear it. Leave it in the comments, and don''t forget to subscribe to Night Loom for more stories that shouldn''t be told twice.", "youtube_description": "A missing keeper, a lighthouse log with a final warning, and a beam that must never stop moving. This is the story of what I found on the headland, and why I still watch the water every night. If you enjoy unsettling mysteries, subscribe to Night Loom for more stories that linger.", "tags": ["horror story", "lighthouse horror", "night loom", "creepy lighthouse", "unexplained mystery", "dark storytelling", "ocean horror", "narrated horror story"]}','93a8f071bb8cdc98','C:\Users\saina\Videos\YT Automation\assets\audio\video_17.mp3','C:\Users\saina\Videos\YT Automation\output\video_17.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_17_thumbnail.png','OOywJnoz2zM','uploaded',NULL,'2026-08-12 04:41:15','2026-08-12T06:16:20.923157+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_17_manifest.json');
INSERT INTO "videos" VALUES(18,NULL,NULL,'facts','short','A','The Mantis Shrimp Sees Hidden Light and Strikes With the Heat of the Sun','There''s an animal that sees a hidden universe of light — and its strike flashes like the surface of the sun.','In the deep, superpower isn''t about size. It''s about seeing the invisible — and striking with the force of a star.','Which surprised you more, the eyes or the strike? Tell me below, and subscribe to Night Loom.','{"title": "The Mantis Shrimp Sees Hidden Light and Strikes With the Heat of the Sun", "hook_line": "There''s an animal that sees a hidden universe of light \u2014 and its strike flashes like the surface of the sun.", "intro_line": "You''re watching Night Loom, and this one rewired my brain.", "scenes": [{"narration": "Around coral reefs hides a tiny hunter with eyes on moving stalks. Humans see the world in three colors. It reads the same scene through twelve to sixteen light receptors, including polarized light \u2014 a whole dimension our vision simply doesn''t have.", "visual_prompt": "Close-up of a mantis shrimp in its burrow, independently moving compound eyes; split-screen comparing human color vision to mantis shrimp vision."}, {"narration": "But its real weapon is folded under its face. Two club-like limbs hold energy like a cocked spring, and when snapped, the water can''t move out of the way in time.", "visual_prompt": "Macro shot of folded mantis shrimp arms; then a slow-motion strike through water with shockwave rings."}, {"narration": "The strike leaves a bubble of low pressure. When the water collapses back in, the bubble dies in a flash of light and heat \u2014 close to the temperature of the sun.", "visual_prompt": "Artistic side view of a cavitation bubble forming and collapsing at the strike point, with a bright flash of light and heat."}, {"narration": "So it doesn''t chase. It waits, reads every color in that moment, and gives all that energy to one perfect strike.", "visual_prompt": "Wide, calm reef scene at dusk; a small mantis shrimp perched on coral waits motionless as light ripples over the seafloor."}], "ending_line": "In the deep, superpower isn''t about size. It''s about seeing the invisible \u2014 and striking with the force of a star.", "cta": "Which surprised you more, the eyes or the strike? Tell me below, and subscribe to Night Loom.", "youtube_description": "The mantis shrimp has some of the most complex eyes in the animal kingdom, and its strike creates a flash of light at nearly the temperature of the sun. This short video follows one tiny ocean hunter as it proves that superpowers don''t need size. If you love world-changing facts, subscribe to Night Loom for more.", "tags": ["mantis shrimp", "ocean facts", "animal superpowers", "hidden colors", "cavitation flash", "marine biology", "nature secrets", "Night Loom"]}','5693551a5000ad6a','C:\Users\saina\Videos\YT Automation\assets\audio\video_18.mp3','C:\Users\saina\Videos\YT Automation\output\video_18.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_18_thumbnail.png','Qv6kgQLunBc','uploaded',NULL,'2026-08-12 06:41:20','2026-08-12T06:53:58.552029+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_18_manifest.json');
INSERT INTO "videos" VALUES(19,NULL,NULL,'mystery','short','A','Why the north fork Mine Whistle Still Blows at 2:17','Why does the abandoned mine whistle in north fork blow at 2:17 every night?','The whistle isn''t a warning. It''s a question from underground.','What do you think is down there? Tell me in the comments, and subscribe to Night Loom for the rest of the evidence.','{"title": "Why the north fork Mine Whistle Still Blows at 2:17", "hook_line": "Why does the abandoned mine whistle in north fork blow at 2:17 every night?", "intro_line": "Welcome to Night Loom, where I collect the sounds the town can''t explain.", "scenes": [{"narration": "The mine closed in 1981. The power was cut, the entrance sealed, yet the whistle still howls at the same minute every night.", "visual_prompt": "Moonlit abandoned mine entrance with rusted whistle tower and sealed concrete doors."}, {"narration": "An engineer recorded the blast. It wasn''t random. It was one long note, two short, one long \u2014 a mining code older than the company. It meant one thing: send the cage.", "visual_prompt": "Sound engineer with headphones watching a waveform on a laptop beside a recording device."}, {"narration": "She opened the last dispatch log from the collapse. The cage at 2:17 carried nine survivors. The tenth line was empty, with a note: Gone back for someone.", "visual_prompt": "A dusty rescue logbook open on a desk, handwritten columns and one empty line."}, {"narration": "At her feet, the recorder caught another signal, deeper, from under the shaft. Same code, slower, like a voice learning to ask again.", "visual_prompt": "A dark mine shaft with a faint light far below; audio recorder on rocky ground."}], "ending_line": "The whistle isn''t a warning. It''s a question from underground.", "cta": "What do you think is down there? Tell me in the comments, and subscribe to Night Loom for the rest of the evidence.", "youtube_description": "The sealed north fork mine still blows its warning whistle at 2:17 every night. I dug through the old rescue records to find why. Drop your theory in the comments and subscribe to Night Loom for more mysteries hidden in plain sight.", "tags": ["north fork mine whistle", "abandoned mine mystery", "2:17 mystery", "Night Loom", "mine collapse legend", "true mystery story", "small town secrets"]}','3b9b0819cee94cba','C:\Users\saina\Videos\YT Automation\assets\audio\video_19.mp3','C:\Users\saina\Videos\YT Automation\output\video_19.mp4','C:\Users\saina\Videos\YT Automation\assets\images\video_19_thumbnail.png','G1vVxluPIFU','uploaded',NULL,'2026-08-12 09:07:52','2026-08-12T09:17:02.921774+00:00','C:\Users\saina\Videos\YT Automation\assets\visuals\video_19_manifest.json');
